/**
 * Phase A Step 4.5: 检测聚类角色中的互斥域冲突并拆分
 *
 * 当同一聚类角色的来源同时命中一对互斥域的两侧关键词（如既有"合规"又有"增长"），
 * 说明约束将两个互斥职责推向了同一角色类型，应拆分为两个独立角色。
 */
export declare function detectAndResolveConflicts(clustered: {
    roleType: string;
    sources: DerivedRoleSource[];
    confidence: number;
}[]): ClusteredRoleWithConflict[];
import type { RoleBlue } from '../../types';
/** 旧 API: 为一个角色筛选候选认知框架 */
export declare function matchFrameworksForRole(role: RoleBlue, taskJob: string, maxCandidates?: number): Framework[];
/** 旧 API: 为整个团队批量匹配 */
export declare function batchMatchFrameworks(roles: RoleBlue[], taskJob: string): Record<string, Framework[]>;
/** 旧 API: 格式化为 LLM prompt */
export declare function formatFrameworksForPrompt(frameworks: Framework[]): string;
